  @FXML
  public void initialize() {
    preferencesRepository = new PreferencesRepository();

    preferencesItem.setGraphic(Fx.createImageView("preferences"));
    preferencesItem.setDisable(!SecurityFactory.getInstance().getSecurityManager().evaluate(
                getDomainContext(), SecurityFactory.getInstance().getExecutePermission(), PreferencesDialog.class).isAccepted());
    preferencesItem.setOnAction(e -> PreferencesDialog.show());

    discardItem.setGraphic(Fx.createImageView("reload"));
    discardItem.setOnAction(e -> loadRepository());

    exitItem.setGraphic(Fx.createImageView("exit"));
    exitItem.setOnAction(e -> exit());

    helpItem.setGraphic(Fx.createImageView("help"));
    helpItem.setOnAction(e -> help());

    aboutItem.setGraphic(Fx.createImageView("about"));
    aboutItem.setOnAction(e -> AboutView.showDialog());

//    preferenceEditor = Fx.load(BundleEditor.class);
//    innerBorderPane.setRight(preferenceEditor.getView());
//
//    preferencesTreeTable.getSelectionModel().getSelectedItems().addListener((ListChangeListener<TreeItem<BundleNode>>) c -> {
//      TreeItem<BundleNode> selectedItem = preferencesTreeTable.getSelectionModel().getSelectedItem();
//      preferenceEditor.setBundleNode(selectedItem == null ? null : selectedItem.getValue());
//    });

    filterField.setAutoSelect(true);
    filterField.setOnAction(e -> {
      if (runFilter()) {
        Platform.runLater(preferencesTreeTable::requestFocus);
      }
      else {
        Platform.runLater(filterField::requestFocus);
      }
    });
    filterField.setTooltip(new Tooltip(resources.getString("filter=F2, clear=Shift-F2")));

    findField.setAutoSelect(true);
    findField.setOnAction(e -> {
      if (!runFind(null)) {
        Platform.runLater(findField::requestFocus);
      }
    });
    findField.setTooltip(new Tooltip(resources.getString("next=F3, previous=Shift-F3")));

    ucLcButton.setBindable(false);
    ucLcButton.setOnAction(event -> lastFilter = null);
    ucLcButton.setTooltip(new Tooltip(resources.getString("toggle case sensitivity")));

    saveButton.setOnAction(e -> save());
  }

  @Override
  public void configure() {
    preferencesTreeTable.setSortable(false);
    preferencesTreeTable.setReorderable(false);
    preferencesTreeTable.setRowFactory(treeTableView -> new TreeTableRow<>() {
      @Override
      protected void updateItem(PreferenceNode item, boolean empty) {
        super.updateItem(item, empty);
        if (item != null) {
            if (item.getModificationCount() != 0) {
              if (!getStyleClass().contains(STYLE_MODIFIED)) {
                getStyleClass().add(STYLE_MODIFIED);
              }
            }
            else {
              getStyleClass().remove(STYLE_MODIFIED);
            }
          }
      }
    });

    // register F-keys
    getView().addEventFilter(KeyEvent.ANY, e -> {
      if (!e.isAltDown() && !e.isControlDown() && !e.isMetaDown() && !e.isShortcutDown()) {
        if (e.getCode() == KeyCode.F3) {
          if (e.getEventType() == KeyEvent.KEY_PRESSED) {
            findField.updateModel();
            if (!runFind(!e.isShiftDown())) {
              Platform.runLater(findField::requestFocus);
            }
            e.consume();
          }
        }
        else if (e.getCode() == KeyCode.F2) {
          if (e.getEventType() == KeyEvent.KEY_PRESSED) {
            if (e.isShiftDown()) {
              // clear filter
              filter = null;
              filterField.updateView();
            }
            else {
              filterField.updateModel();
            }
            if (runFilter()) {
              Platform.runLater(preferencesTreeTable::requestFocus);
            }
            else {
              Platform.runLater(filterField::requestFocus);
            }
            e.consume();
          }
        }
      }
    });

    preferenceNodeTablePopup = Rdc.createTablePopup(preferencesTreeTable, "preferencesTreeTable", resources.getString("Bundles"));
    preferenceNodeTablePopup.setColumnMenuEnabled(false);
    preferenceNodeTablePopup.loadPreferences();
    preferencesRepository.addPreferencesUpdatedListener(this::preferencesUpdated);
    loadRepository();
    configureContextMenu();
  }

  /**
   * Asks the user whether to exit the application and does so if yes.
   */
  public void exit() {
    Fx.yes(preferencesRepository.getModificationCount() != 0 ?
           resources.getString("ExitModifiedAction") :
           resources.getString("ExitAction"),
           false, Platform::exit);
  }


  /**
   * Configures the context menu of the tree table.
   */
  private void configureContextMenu() {
    ContextMenu contextMenu = preferencesTreeTable.getContextMenu();
    MenuItem renameBundleItem = new MenuItem();
    renameBundleItem.setText(resources.getString("rename preference"));
//    renameBundleItem.setOnAction(e -> renameBundle());
    contextMenu.getItems().add(0, renameBundleItem);
    MenuItem renamePackageItem = new MenuItem();
    renamePackageItem.setText(resources.getString("rename package"));
//    renamePackageItem.setOnAction(e -> renamePackage());
    contextMenu.getItems().add(0, renamePackageItem);
    contextMenu.addEventHandler(WindowEvent.WINDOW_SHOWING, event -> {
      TreeItem<PreferenceNode> selectedItem = preferencesTreeTable.getSelectionModel().getSelectedItem();
      boolean disable = selectedItem == null || preferencesRepository.getModificationCount() != 0;
      renameBundleItem.setDisable(disable);
      renamePackageItem.setDisable(disable);
    });
  }

  /**
   * Applies the filter to the shown tree items.
   *
   * @return true if filter applied, else all shown
   */
  private boolean runFilter() {
    boolean filtered = false;
    if (!Objects.equals(filter, lastFilter)) {
      lastFilter = filter;
      if (!StringHelper.isAllWhitespace(filter)) {
        boolean ucLcSensitive = ucLcButton.isSelected();
        String lcFilter = ucLcSensitive ? filter : filter.toUpperCase();
        boolean not = false;
        if (lcFilter.startsWith("!") || lcFilter.startsWith("-")) {
          not = true;
          lcFilter = lcFilter.substring(1);
        }
        List<PreferenceNode> foundNodes = new ArrayList<>();
        for (PreferenceNode preferenceNode : preferencesRepository.getPreferences()) {
          String name = ucLcSensitive ? preferenceNode.getName() : preferenceNode.getName().toUpperCase();
          if (name.contains(lcFilter) ^ not) {
            foundNodes.add(preferenceNode);
          }
        }
        preferences = foundNodes;
        filtered = true;
      }
      else {
        preferences = preferencesRepository.getPreferences();
      }
      preferenceTreeItems = null;
      preferencesTreeTable.updateView();
    }
    return filtered;
  }

  /**
   * Finds the next/previous key or translation.
   *
   * @param next true if start search at next item, false if search backwards starting at previous item, null if find next starting at current item
   * @return true if found
   */
  private boolean runFind(Boolean next) {
    if (!Objects.equals(find, lastFind)) {
      foundItem = null;
      foundIndex = -1;
      foundLocale = null;
    }
    boolean found = false;
    lastFind = find;
    if (!StringHelper.isAllWhitespace(find)) {
      if (preferenceTreeItems == null) {
        preferenceTreeItems = preferencesTreeTable.getTreeItems();
        foundItem = null;
        foundLocale = null;
      }
      if (preferenceTreeItems.size() > 1) {
        if (foundItem == null) {
          // take selected item as starting point
          foundItem = preferencesTreeTable.getSelectionModel().getSelectedItem();
        }
        if (foundItem == null) {
          // no selected item: start from beginning
          foundItem = preferenceTreeItems.get(0);
          foundIndex = 0;
        }
        else {
          foundIndex = preferenceTreeItems.indexOf(foundItem);
        }
        found = runFind(foundItem, foundIndex, foundLocale, next);
      }
    }
    return found;
  }

  /**
   * Finds the next/previous key or translation.
   *
   * @param item the current item to start
   * @param itemNdx the index of the item in preferenceTreeItems
   * @param locale != null if check translations first
   * @param next true if start search at next item, false if search backwards starting at previous item, null if find next starting at current item
   * @return true if found
   */
  private boolean runFind(TreeItem<PreferenceNode> item, int itemNdx, String locale, Boolean next) {
    String ucFind = ucLcButton.isSelected() ? find : find.toUpperCase();
    if (item.isLeaf()) {
//      if (checkTranslations(item, ucFind, locale == null ? -1 : locales.indexOf(locale), next)) {
//        foundIndex = itemNdx;
//        showFoundItem();
//        return true;
//      }
    }

    // nothing more found in translations
    foundLocale = null;

    Holder<TreeItem<PreferenceNode>> itemHolder = new Holder<>();
    itemHolder.accept(item);
    int startNdx = itemNdx;
    if (next != null) {
      if (next) {
        startNdx = toNextItem(itemNdx, itemHolder);
      }
      else {
        startNdx = toPreviousItem(itemNdx, itemHolder);
      }
    }

    itemNdx = startNdx;
    do {
      item = itemHolder.get();
      String name = item.getValue().getName();
      if (!ucLcButton.isSelected()) {
        name = name.toUpperCase();
      }
      if (name.contains(ucFind)) {
        foundIndex = itemNdx;
        foundItem = item;
        foundLocale = null;
        showFoundItem();
        return true;
      }
//      if (item.isLeaf() && checkTranslations(item, ucFind,-1, next)) {
//        foundIndex = itemNdx;
//        showFoundItem();
//        return true;
//      }
      if (Boolean.FALSE.equals(next)) {
        itemNdx = toPreviousItem(itemNdx, itemHolder);
      }
      else {
        itemNdx = toNextItem(itemNdx, itemHolder);
      }
    } while (itemNdx != startNdx);

    return false;
  }



  /**
   * Moves the current item to the next within the item tree.
   *
   * @param itemNdx the index of all tree items
   * @param itemHolder the holder of the current/next tree item
   * @return the new item index
   */
  private int toNextItem(int itemNdx, Holder<TreeItem<PreferenceNode>> itemHolder) {
    if (itemNdx < preferenceTreeItems.size() - 1) {
      itemNdx++;
    }
    else {
      itemNdx = 0;    // wrap
    }
    itemHolder.accept(preferenceTreeItems.get(itemNdx));
    return itemNdx;
  }

  /**
   * Moves the current item to the previous within the item tree.
   *
   * @param itemNdx the index of all tree items
   * @param itemHolder the holder of the current/previous tree item
   * @return the new item index
   */
  private int toPreviousItem(int itemNdx, Holder<TreeItem<PreferenceNode>> itemHolder) {
    if (itemNdx > 0) {
      itemNdx--;
    }
    else {
      itemNdx = preferenceTreeItems.size() - 1;   // wrap
    }
    itemHolder.accept(preferenceTreeItems.get(itemNdx));
    return itemNdx;
  }

  /**
   * Shows the currently found item.
   */
  private void showFoundItem() {
    // make sure item is visible
    TreeItem<PreferenceNode> item = foundItem;
    do {
      if (!item.isExpanded()) {
        item.setExpanded(true);
      }
      item = item.getParent();
    } while (item != null);
    int row = preferencesTreeTable.getRow(foundItem);
    if (row >= 0) {
      preferencesTreeTable.scrollToCentered(row);
      preferencesTreeTable.getSelectionModel().select(foundItem);
//      if (foundLocale == null) {
//        preferencesTreeTable.requestFocus();
//        preferenceEditor.setBundleNode(foundItem.getValue());
//      }
//      else {
//        preferenceEditor.setBundleNode(foundItem.getValue());
//        preferenceEditor.selectLocale(foundLocale);
//      }
    }
  }

  /**
   * Saves all changes to the database.
   */
  private void save() {
    preferencesRepository.persist();
    loadRepository();
  }

